"""Small pure functions."""


def add(a, b):
    return a + b


def sub(a, b):
    return a - b


def neg(a):
    return a

import unittest

from mathlib import add, neg, sub


class AddTest(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)

    def test_sub(self):
        self.assertEqual(sub(5, 3), 2)

    def test_neg(self):
        self.assertEqual(neg(0), 0)


if __name__ == "__main__":
    unittest.main()

