def add(a, b):
    return a + b


def sub(a, b):
    return a - b


def neg(a):
    return -a


def mul(a, b):
    return a * b


def square(a):
    return a * a

import unittest

from mathlib import add, mul, neg, square, sub


class AddTest(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)

    def test_sub(self):
        self.assertEqual(sub(5, 3), 2)

    def test_neg(self):
        self.assertEqual(neg(4), -4)

    def test_mul(self):
        self.assertEqual(mul(4, 3), 12)

    def test_square(self):
        self.assertEqual(square(5), 25)


if __name__ == "__main__":
    unittest.main()
